-- Generated by `npm run train:county-rpp`; do not edit by hand.
begin;

delete from public.county_rpp_estimates as estimate
using public.regions as region
where region.type = 'county'
  and region.fips = estimate.county_fips
  and region.msa_id is not null;

on conflict (county_fips, year) do update set
  predicted_rpp_all_items = excluded.predicted_rpp_all_items,
  predicted_rpp_housing = excluded.predicted_rpp_housing,
  confidence_interval = excluded.confidence_interval,
  model_version = excluded.model_version,
  source = excluded.source;

commit;
